<script setup lang="ts">
import { computed, reactive } from 'vue'
import { anniversary, ipRights, isProcurement, type Procurement } from '@/api/modules/procurement'
import { isTerms, type ProductData } from '@/api/modules/licensing'
import {validSupplyId,type WorkRecord,type MediaType} from '@/api/modules/supply'
import SupplyUpload from './SupplyUpload.vue'
const props=defineProps<{works:WorkRecord[];disabled:boolean;assets:Record<string,string[]>}>(),emit=defineEmits<{submit:[Omit<ProductData,'review'>&{previous_product_id:string|null}];upload:[File,MediaType,string];remove:[string,string]}>()
const f=reactive({mode:'',work:'',title:'',preview:'',buyer:'',start:'',attribution:'',coauthors:'',cycle:'',annexTerms:'',terms:'',rule:'',minutes:'',confirmed:false})
const files=[['rights_chain_ids','完整权利链依据'],['ownership_proof_ids','权属证明'],['original_creation_ids','原始创作依据']] as const
const amount=computed(()=>f.mode==='BUYOUT'?5000000:0)
const payload=computed(()=>{
 if(!['BUYOUT','REVENUE_SHARE'].includes(f.mode)||!validSupplyId(f.work)||!validSupplyId(f.buyer)||!f.title.trim()||!f.preview.trim()||!f.start||!Number.isFinite(Date.parse(f.start))||!f.coauthors||!validSupplyId(f.rule)||!/^\d+$/.test(f.minutes)||+f.minutes<1||+f.minutes>10080||!f.confirmed)return null
 const start=new Date(f.start).toISOString(),buy=f.mode==='BUYOUT'
 const terms={contract_kind:buy?'IP_BUYOUT_20261029' as const:'IP_REVENUE_SHARE_20261029' as const,exclusive:true,rights:[...ipRights],purposes:['PRIVATE','PUBLIC_SHARE','COMMERCIAL','RELEASE'] as const,territories:['WORLD'],languages:['ALL'],valid_from:start,development_until:buy?null:anniversary(start,2),valid_until:buy?null:anniversary(start,5),project_limit:null,episode_limit:null,terms_text:f.terms.trim()}
 const procurement={version:'CONTRACT_20261029',mode:f.mode,buyer_party_id:f.buyer,upfront_minor:amount.value,royalty_bps:buy?0:800,sublicensing_allowed:true,attribution_terms:f.attribution.trim(),rights_evidence:{rights_chain_ids:props.assets.rights_chain_ids||[],ownership_proof_ids:props.assets.ownership_proof_ids||[],original_creation_ids:props.assets.original_creation_ids||[],has_coauthors:f.coauthors==='yes',coauthor_consent_ids:props.assets.coauthor_consent_ids||[]},settlement_annex:buy?null:{asset_id:props.assets.settlement_annex?.[0],cycle:f.cycle,terms_text:f.annexTerms.trim(),net_basis:'ALL_RELEASE_AND_DERIVATIVE_INCOME_LESS_PLATFORM_TAX_DISTRIBUTION_PRODUCTION'}}
 if(!isTerms(terms)||!isProcurement(procurement))return null
 return {work_version_id:f.work,previous_product_id:null,title:f.title.trim(),preview_text:f.preview.trim(),terms,procurement:procurement as Procurement,price:{currency:'CNY',amount_minor:amount.value},payment_due_minor:amount.value,reservation_minutes:+f.minutes,rule_id:f.rule}
})
</script>
<template><form class="license-form" data-testid="ip-product-form" @submit.prevent="payload&&emit('submit',payload)"><fieldset :disabled="disabled"><section class="supply-card"><h2>指定平台 IP 采购</h2><p>仅供稿方、指定采购方及独立审核人办理。附件受控读取，不向普通目录公开。</p><label>已双审的原作 *<select v-model="f.work" required><option value="">请选择明确版本</option><option v-for="w in works" :key="w.id" :value="w.id">{{w.data.version.content.title}} · {{w.revision}}</option></select></label><label>本份采购方案 *<select v-model="f.mode" required><option value="">请主动选择</option><option value="BUYOUT">本合同买断：人民币50,000元，分红0%</option><option value="REVENUE_SHARE">本合同分红：前置0元，净收益8%</option></select></label><p v-if="f.mode==='BUYOUT'">永久、全球独家，无项目或集数上限。须核验本合同全额付款与双方签署后才生效；不是所有作品统一售价。</p><p v-if="f.mode==='REVENUE_SHARE'">5个日历年授权、2年开发期、无数量上限。零前置仍承担净收益8%义务；开发、上线和撤回须有独立核验依据。</p><label>指定平台采购主体编号 *<input v-model.trim="f.buyer" required></label><label>合同许可开始（本地时间） *<input v-model="f.start" type="datetime-local" required></label><label>商品标题 *<input v-model="f.title" maxlength="200" required></label><label>已获准公开短试读 *<textarea v-model="f.preview" maxlength="2000" required></textarea></label><label>署名约定 *<textarea v-model="f.attribution" maxlength="2000" required></textarea></label><p>合同允许转许可不等于已经产生下游授权；新的授权与审核另行办理。</p></section><section class="supply-card"><h2>分类权属材料</h2><SupplyUpload v-for="([key,label]) in files" :key="key" :label="label" :ids="assets[key]||[]" :disabled="disabled" @remove="id=>emit('remove',key,id)" @upload="(file,media)=>emit('upload',file,media,key)"/><p v-for="([key,label]) in files" :key="key">{{label}}：{{(assets[key]||[]).join('、')||'尚未上传'}}</p><label>是否有共同作者 *<select v-model="f.coauthors" required><option value="">请核实后选择</option><option value="yes">有，须提供共同作者同意</option><option value="no">没有</option></select></label><template v-if="f.coauthors==='yes'"><SupplyUpload label="共同作者同意依据" :ids="assets.coauthor_consent_ids||[]" :disabled="disabled" @remove="id=>emit('remove','coauthor_consent_ids',id)" @upload="(file,media)=>emit('upload',file,media,'coauthor_consent_ids')"/><p>{{(assets.coauthor_consent_ids||[]).join('、')||'尚未上传'}}</p></template><template v-if="f.mode==='REVENUE_SHARE'"><SupplyUpload label="本合同结算附件" :ids="assets.settlement_annex||[]" :single="true" :disabled="disabled" @remove="id=>emit('remove','settlement_annex',id)" @upload="(file,media)=>emit('upload',file,media,'settlement_annex')"/><p>{{assets.settlement_annex?.[0]||'尚未上传'}}</p><label>结算周期 *<select v-model="f.cycle" required><option value="">请明确选择</option><option value="MONTHLY">按月</option><option value="QUARTERLY">按季度</option><option value="ANNUAL">按年</option><option value="AGREED">按附件约定</option></select></label><label>结算附件具体约定 *<textarea v-model="f.annexTerms" maxlength="8000" required></textarea></label><p>净收益口径：全部发行及衍生收入，扣除平台佣金、税费、发行成本、制作成本。账单审核不表示转账。</p></template></section><section class="supply-card"><label>完整合同条款 *<textarea v-model="f.terms" maxlength="8000" required></textarea></label><label>已核验生效规则编号 *<input v-model.trim="f.rule" required></label><label>预留时长（分钟） *<input v-model="f.minutes" inputmode="numeric" required></label><label><input v-model="f.confirmed" type="checkbox">我已核对本次方案、实际材料与指定采购方；提交等待独立审核，尚未付款或签署。</label><button class="primary" :disabled="disabled||!payload">提交 IP 采购商品审核</button></section></fieldset></form></template>
